{"success": true, "data": {"stdout": "import json, csv, os
from collections import defaultdict

BASE = "/root/occsafe_vla/artifacts/gradient_analysis_mixed_seed"
conditions = ["Full_OCC_s0", "Random_s2"]
data = {}
for c in conditions:
    with open(os.path.join(BASE, f"{c}_gradient_stats.json")) as f:
        data[c] = json.load(f)["layers"]

def get_group(layer_name):
    prefix, idx = layer_name.rsplit("_", 1)
    idx = int(idx)
    if prefix == "dino":
        if idx <= 7: return "early"
        elif idx <= 15: return "mid"
        else: return "late"
    else:
        if idx <= 8: return "early"
        elif idx <= 17: return "mid"
        else: return "late"

def is_zero(stats):
    return stats["action_grad_norm"]["mean"] == 0 and stats["aux_grad_norm"]["mean"] == 0

# Per-layer CSV (exclude zeros)
rows = []
for cond in conditions:
    for ln, stats in data[cond].items():
        if is_zero(stats):
            continue
        prefix, idx_s = ln.rsplit("_", 1)
        rows.append({
            "condition": cond, "encoder": prefix, "layer_idx": int(idx_s),
            "layer_name": ln, "group": get_group(ln),
            "conflict_rate": round(stats["conflict_rate"]["mean"], 6),
            "cosine_sim": round(stats["cosine_similarity"]["mean"], 6),
            "action_grad_norm": round(stats["action_grad_norm"]["mean"], 6),
            "aux_grad_norm": round(stats["aux_grad_norm"]["mean"], 6),
        })

csv_path = os.path.join(BASE, "per_layer_conflict_rate.csv")
with open(csv_path, "w", newline="") as f:
    w = csv.DictWriter(f, fieldnames=["condition","encoder","layer_idx","layer_name","group",
                                       "conflict_rate","cosine_sim","action_grad_norm","aux_grad_norm"])
    w.writeheader()
    w.writerows(rows)

# Group summaries (combined + per-encoder)
def compute_group_stats(cond_data, filter_enc=None):
    groups = defaultdict(lambda: {"crs": [], "css": [], "layers": []})
    for ln, stats in cond_data.items():
        if is_zero(stats):
            continue
        prefix = ln.rsplit("_", 1)[0]
        if filter_enc and prefix != filter_enc:
            continue
        g = get_group(ln)
        groups[g]["crs"].append(stats["conflict_rate"]["mean"])
        groups[g]["css"].append(stats["cosine_similarity"]["mean"])
        groups[g]["layers"].append(ln)
    result = {}
    for g in ["early", "mid", "late"]:
        d = groups[g]
        if not d["crs"]:
            continue
        layers_sorted = sorted(d["layers"], key=lambda x: (x.rsplit("_",1)[0], int(x.rsplit("_",1)[1])))
        result[g] = {
            "conflict_rate": round(sum(d["crs"])/len(d["crs"]), 6),
            "cosine_sim": round(sum(d["css"])/len(d["css"]), 6),
            "num_layers": len(d["crs"]),
            "layers": f"{layers_sorted[0]}..{layers_sorted[-1]}"
        }
    return result

print("=" * 80)
print("COMBINED GROUP SUMMARY (zero-gradient layers excluded)")
print("=" * 80)
registry_data = {}
for cond in conditions:
    gs = compute_group_stats(data[cond])
    registry_data[cond] = {}
    print(f"\n--- {cond} ---")
    print(f"{'Group':<8} {'N':>3} {'ConflictRate':>13} {'CosineSim':>11} {'Layers'}")
    for g in ["early", "mid", "late"]:
        s = gs[g]
        print(f"{g:<8} {s['num_layers']:>3} {s['conflict_rate']:>13.6f} {s['cosine_sim']:>11.6f} {s['layers']}")
        registry_data[cond][g] = {
            "conflict_rate": s["conflict_rate"],
            "cosine_sim": s["cosine_sim"],
            "num_layers": s["num_layers"],
            "layers": s["layers"]
        }

print("\n" + "=" * 80)
print("PER-ENCODER GROUP SUMMARY")
print("=" * 80)
for cond in conditions:
    print(f"\n--- {cond} ---")
    for enc in ["dino", "siglip"]:
        gs = compute_group_stats(data[cond], filter_enc=enc)
        print(f"\n  {enc.upper()} (zero layers excluded):")
        print(f"  {'Group':<8} {'N':>3} {'ConflictRate':>13} {'CosineSim':>11}")
        for g in ["early", "mid", "late"]:
            if g in gs:
                s = gs[g]
                print(f"  {g:<8} {s['num_layers']:>3} {s['conflict_rate']:>13.6f} {s['cosine_sim']:>11.6f}")
                registry_data[cond][f"{enc}_{g}"] = {
                    "conflict_rate": s["conflict_rate"],
                    "cosine_sim": s["cosine_sim"],
                    "num_layers": s["num_layers"],
                }

with open(os.path.join(BASE, "per_layer_summary.json"), "w") as f:
    json.dump(registry_data, f, indent=2)

print(f"\nSaved: {csv_path}")
print(f"Saved: {os.path.join(BASE, 'per_layer_summary.json')}")
